import{_ as r,l as n,o as e,c as l,v as t,p as s,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"单调队列优化","description":"","frontmatter":{"title":"单调队列优化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/monotone-queue-opt.md","filePath":"cs/monotone-queue-opt.md","lastUpdated":1789023840000}'),c={name:"cs/monotone-queue-opt.md"};function _(u,a,m,E,P,f){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="单调队列优化" tabindex="-1">单调队列优化 <a class="header-anchor" href="#单调队列优化" aria-label="Permalink to &quot;单调队列优化&quot;">​</a></h1><div class="epigraph"><p>转移 $dp[i]=\\min_{j\\in[i-w,i)} (dp[j]+c[j])$ 且候选随 $i$ 滑动时，队头过期、队尾维护单调，均摊 $O(1)$ 转移。</p><footer>—— 据 Knuth TAOCP 与滑动窗口最小值；CLRS 第 15 章 DP 整理</footer></div><p>上一课<a href="/cs/digit-dp">数位 DP</a>沿位数。数值 DP 常 \\(O(n^2)\\) 枚举切点。缺口是窗口内最值：单调队列（deque）维护下标递增、键单调。不重写数位自动机。后课斜率优化窗口变成凸包。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(dp[i]=\\min_{i-w\\le j\\lt i} dp[j]+b[i]\\)（\\(b\\) 与 \\(j\\) 无关）即滑动 \\(\\min\\)。队头弹出 \\(j\\le i-w\\)，队尾弹出不如新 \\(i-1\\) 的。每个下标进出一次，\\(O(n)\\)。\\(c[j]\\) 依赖 \\(j\\) 时键为 \\(dp[j]+c[j]\\)，同样单调队列若比较与 \\(i\\) 无关。</p><p>若决策 \\(j\\) 的优劣随 \\(i\\) 交叉（斜率），本课不够，下一课 CHT。</p><h3 id="不是优先队列" tabindex="-1">不是优先队列 <a class="header-anchor" href="#不是优先队列" aria-label="Permalink to &quot;不是优先队列&quot;">​</a></h3><p>优先队列给全局最值，删过期要惰性。窗口滑动用双端队列更干净。不要一上来堆。</p><p><span class="marginnote">滑动窗口最小值是经典。多重背包二进制/单调队列是应用。后课凸包维护与 \\(i\\) 相关的比较。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>递增下标队列。转移前弹头弹尾，取队头为最优 \\(j\\)。背包：容量滚动 + 余数分组队列。</p>',11)),(e(),s(h,null,{default:i(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E9%98%B6%E6%AE%B5%20i%22%5D%20--%3E%20POP%5B%22%E5%BC%B9%E8%BF%87%E6%9C%9F%E9%98%9F%E5%A4%B4%22%5D%0A%20%20POP%20--%3E%20TAIL%5B%22%E5%BC%B9%E4%B8%8D%E4%BC%98%E9%98%9F%E5%B0%BE%22%5D%0A%20%20TAIL%20--%3E%20HD%5B%22%E9%98%9F%E5%A4%B4%20%3D%20%E6%9C%80%E4%BC%98%20j%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>键必须与队内比较无关 \\(i\\)，或随 \\(i\\) 同向移动。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若 \\(j_1\\lt j_2\\) 且 \\(j_2\\) 不差于 \\(j_1\\)，则 \\(j_1\\) 永不再优，可从尾删。窗口左端单调，从头删。均摊线性。与树状数组：窗口最值也可用 ST 表 \\(O(1)\\)，但单调队列 \\(O(n)\\) 预处理零、在线友好。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写决策单调的分治（后课）。不写三维单调队列。后课默认：滑动窗口最值转移用单调队列。下一课斜率优化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窗口最值：双端队列均摊 \\(O(1)\\)。</li><li>决策交叉则换斜率/分治。</li><li>每个下标进出一次。</li><li>出处：滑动窗口与 Knuth 队列思想；CLRS DP。</li></ul>',7))])}const j=r(c,[["render",_]]);export{T as __pageData,j as default};
